function icon(string $name, int $size = 24, string $class = ''): string
{
    $icons = icon_list();
    $body  = $icons[$name] ?? $icons['grid'];

    return '<svg class="icon ' . htmlspecialchars($class, ENT_QUOTES) . '" width="' . $size . '" height="' . $size . '"'
        . ' viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"'
        . ' stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' . $body . '</svg>';
}

function color_list(): array
{
    return ['indigo', 'violet', 'blue', 'sky', 'teal', 'green', 'amber', 'orange', 'rose', 'red', 'pink', 'slate'];
}
